insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 51.588658, 0.034456, 'zebra', 'Pedestrian crossing — scan pavements early and be ready to stop smoothly.', 'medium' from routes where name = 'Route 1 · Town loop' and centre_id = (select id from test_centres where name = 'Wanstead');
