insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 51.417999, -0.149676, 'junction', 'Tight junction — position early and check both mirrors before turning.', 'medium' from routes where name = 'Route 1 · Town loop' and centre_id = (select id from test_centres where name = 'Mitcham');
insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 51.418949, -0.153897, 'roundabout', 'Busy roundabout — mirror-signal-position on approach, watch lane discipline on exit.', 'low' from routes where name = 'Route 1 · Town loop' and centre_id = (select id from test_centres where name = 'Mitcham');
