insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 52.37707, -1.506435, 'junction', 'Tight junction — position early and check both mirrors before turning.', 'medium' from routes where name = 'Route 2 · Residential circuit' and centre_id = (select id from test_centres where name = 'Coventry');
insert into hazards (id, route_id, lat, lng, type, description, severity) select gen_random_uuid(), id, 52.374477, -1.504485, 'roundabout', 'Busy roundabout — mirror-signal-position on approach, watch lane discipline on exit.', 'low' from routes where name = 'Route 2 · Residential circuit' and centre_id = (select id from test_centres where name = 'Coventry');
